insert into workflow.definitions (id, version, tenant_id, name, status, origin, owning_module, owner_id, definition, created_at, updated_at) values ('50000000-0000-0000-0000-000000000001', 1, '00000000-0000-0000-0000-000000000001', 'Invoice approval', 'Active', 'ModuleTemplate', 'document-management', '10000000-0000-0000-0000-000000000001', '{"id":"50000000-0000-0000-0000-000000000001","version":1,"name":"Invoice approval","description":"Submitted invoices are pre-checked by the AI agent, routed by its recommendation and approved by a person with an approval limit.","origin":"moduleTemplate","owningModule":"document-management","startStepId":"lookup","steps":[{"id":"lookup","kind":"moduleStep","title":"Load invoice data","stepTypeId":"documents.lookupInvoice","stepTypeVersion":1,"parameters":{"invoiceId":"vars.invoiceId"},"outputMapping":{},"options":[],"tools":[],"approvers":[],"requiresHuman":false,"aiAllowed":true,"critical":false,"maxRetries":2,"isHumanOnly":false,"isInteractive":false},{"id":"review","kind":"input","title":"Review the invoice","description":"Check supplier, amount and cost centre and recommend a decision.","input":{"schemaId":"documents.invoiceReview","version":1,"fields":[{"name":"invoiceId","type":"text","label":"documents:field.invoiceId","required":true,"options":[],"sensitive":false,"span":"full"},{"name":"supplier","type":"text","label":"documents:field.supplier","required":false,"options":[],"sensitive":false,"span":"full"},{"name":"amount","type":"number","label":"documents:field.amount","required":true,"min":0,"options":[],"sensitive":false,"span":"half"},{"name":"costCenter","type":"entityRef","label":"documents:field.costCenter","required":false,"options":[],"lookup":"/api/documents/lookups/cost-centers","sensitive":false,"span":"half"},{"name":"recommendation","type":"choice","label":"documents:field.recommendation","required":true,"options":[{"value":"approve","label":"documents:recommendation.approve"},{"value":"reject","label":"documents:recommendation.reject"},{"value":"clarify","label":"documents:recommendation.clarify"}],"sensitive":false,"span":"full"},{"name":"note","type":"multiLine","label":"documents:field.note","required":false,"maxLength":500,"options":[],"sensitive":false,"span":"full"}]},"stepTypeVersion":1,"parameters":{},"outputMapping":{},"options":[],"tools":["documents.lookupInvoice"],"approvers":[],"requiresHuman":false,"aiAllowed":true,"critical":false,"maxRetries":2,"isHumanOnly":false,"isInteractive":true},{"id":"clarify","kind":"approval","title":"Decide on the invoice","description":"The review recommends a clarification - approve or reject.","stepTypeVersion":1,"parameters":{},"outputMapping":{},"options":[],"tools":[],"approvers":["documents.approve"],"requiresHuman":false,"aiAllowed":true,"critical":false,"maxRetries":2,"isHumanOnly":true,"isInteractive":true},{"id":"approve","kind":"moduleStep","title":"Approve the invoice","stepTypeId":"documents.approveInvoice","stepTypeVersion":1,"parameters":{"invoiceId":"vars.invoiceId","comment":"coalesce(vars.note, \u0027Approved in workflow\u0027)"},"outputMapping":{},"options":[],"tools":[],"approvers":[],"requiresHuman":false,"aiAllowed":true,"critical":true,"maxRetries":2,"isHumanOnly":false,"isInteractive":false},{"id":"reject","kind":"moduleStep","title":"Reject the invoice","stepTypeId":"documents.rejectInvoice","stepTypeVersion":1,"parameters":{"invoiceId":"vars.invoiceId","comment":"coalesce(vars.note, steps.clarify.comment, \u0027Rejected in workflow\u0027)"},"outputMapping":{},"options":[],"tools":[],"approvers":[],"requiresHuman":false,"aiAllowed":true,"critical":true,"maxRetries":2,"isHumanOnly":false,"isInteractive":false}],"transitions":[{"from":"lookup","to":"review","order":0},{"from":"review","to":"approve","condition":"vars.recommendation == \u0027approve\u0027","order":1},{"from":"review","to":"reject","condition":"vars.recommendation == \u0027reject\u0027","order":2},{"from":"review","to":"clarify","order":3},{"from":"clarify","to":"approve","condition":"last.decision == \u0027approve\u0027","order":1},{"from":"clarify","to":"reject","order":2},{"from":"approve","to":"end","order":0},{"from":"reject","to":"end","order":0}],"variables":[{"name":"invoiceId","type":"text","sensitive":false},{"name":"supplier","type":"text","sensitive":false},{"name":"amount","type":"number","sensitive":false},{"name":"costCenter","type":"text","sensitive":false},{"name":"recommendation","type":"text","sensitive":false},{"name":"note","type":"text","sensitive":false}],"triggers":[{"id":"submitted","kind":"event","eventType":"documents.invoice.submitted","filter":"payload.category == \u0027invoice\u0027","intervalSeconds":300,"payloadMapping":{"invoiceId":"payload.invoiceId"},"executor":"ai","runAs":"10000000-0000-0000-0000-000000000002","enabled":true,"suspended":false,"deduplicationKey":"payload.invoiceId","maxConcurrentRuns":10}],"aiPolicy":{"autonomy":"approveCritical","allowedSteps":[],"approvers":["documents.approve"],"approvalTimeoutMinutes":1440,"maxRunsPerDay":200,"maxStepsPerRun":25,"maxTokensPerRun":20000,"timeLimitMinutes":30,"dataScope":[],"modelProfile":"default","requiredConfidence":0.7,"fallback":"handOverToHuman"},"dependencies":[{"kind":"module","id":"document-management","version":"^1.0.0","usedBySteps":["approve","lookup","reject","review","trigger:submitted"]},{"kind":"inputSchema","id":"documents.invoiceReview","version":"1","usedBySteps":["review"]},{"kind":"stepType","id":"documents.approveInvoice","version":"1","usedBySteps":["approve"]},{"kind":"stepType","id":"documents.lookupInvoice","version":"1","usedBySteps":["lookup"]},{"kind":"stepType","id":"documents.rejectInvoice","version":"1","usedBySteps":["reject"]},{"kind":"event","id":"documents.invoice.submitted","version":"1","usedBySteps":["trigger:submitted"]}],"status":"active","permissions":{"view":[],"edit":[],"start":[]},"ownerId":"10000000-0000-0000-0000-000000000001","updatedAt":"2026-11-01T08:00:00+0