nd":"inputSchema","id":"users.onboarding","version":"1","usedBySteps":["data"]},{"kind":"stepType","id":"users.createUser","version":"1","usedBySteps":["create"]}],"status":"active","permissions":{"view":[],"edit":[],"start":["users.view"]},"ownerId":"10000000-0000-0000-0000-000000000001","updatedAt":"2026-11-01T08:00:00+00:00"}'::jsonb, '2026-11-01T08:00:00.0000000+00:00', '2026-11-01T08:00:00.0000000+00:00');
